import { getOSByUserAgent } from '@toss/utils';
import { useComBankInfo } from '~/entities/comcode/lib/use-com-bank-info';
import { useGetUserInfoQuery } from '~/entities/user/api/use-get-cstmr-query';
import { appConfig } from '~/shared/config';
import { NativeFunction } from '~/shared/constants/native-function';
import i18n from '~/shared/i18n/i18n';
import { snackBar } from '~/shared/lib/toast';

type CopyTextProps = {
  value: string;
  label: string;
};

export const useCopy = () => {
  const { data: userRes } = useGetUserInfoQuery();
  const { bankName } = useComBankInfo(appConfig.BANK_CODE ?? '');

  const copyWalletAddress = () => {
    copyText({
      value: `${bankName} ${userRes?.tbCstmrMastr?.aliasNm}`,
      label: i18n.t('text:walletAddressCopied'),
    });
  };

  const copyBankAccount = () => {
    copyText({
      value: `${userRes?.tbCstmrMastr?.realAcnutNo}`,
      label: i18n.t('text:accountNumberCopied'),
    });
  };

  const copyText = ({ value, label }: CopyTextProps) => {
    if (getOSByUserAgent() !== 'android') snackBar(label);
    const textToCopy = value;

    if (!window.ReactNativeWebView) {
      navigator.clipboard.writeText(textToCopy);
      return;
    }
    window.webViewBridge.send(NativeFunction.CopyToClipboard, textToCopy);
  };

  return { copyWalletAddress, copyBankAccount, copyText };
};
